mapper.select:
SELECT 
FROM TBL_REGULATORY_NOTIFICATION
WHERE DELETE_FLAG = 0

    AND NOTIFICATION_CODE LIKE CONCAT('%', #{notificationCode}, '%')


    AND NOTIFICATION_TITLE LIKE CONCAT('%', #{notificationTitle}, '%')


    AND NOTIFICATION_TYPE = #{notificationType}


    AND AUTHORITY_ID = #{authorityId}


    AND PRIORITY_LEVEL = #{priorityLevel}


    AND SEND_STATUS = #{sendStatus}


    AND COMPANY_ID = #{companyId}

ORDER BY CREATED_TIME DESC

mapper.update:
UPDATE TBL_REGULATORY_NOTIFICATION
SET SEND_STATUS = #{sendStatus}, UPDATED_TIME = SYSDATE
WHERE NOTIFICATION_ID = #{notificationId}
